13	constexpr int32_t BUFFER_NUM = 2;
14	
15	// Helper: CopyIn (GM → UB) - needs 4 args with padParams
16	template <typename T>
17	__aicore__ inline void CopyInHelper(AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t count)
18	{
19	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
20	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
21	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
22	}
23	
24	// Helper: CopyOut (UB → GM) - needs 3 args
25	template <typename T>
26	__aicore__ inline void CopyOutHelper(const AscendC::GlobalTensor<T> &dst, AscendC::LocalTensor<T> &src, uint32_t count)
27	{
28	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
29	    AscendC::DataCopyPad(dst, src, copyParams);
30	}
