32	template <typename T>
33	class KernelAbsMath {
34	public:
35	    __aicore__ inline KernelAbsMath() {}
36	
37	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
38	                                int64_t formerNum, int64_t formerLength,
39	                                int64_t tailLength, int64_t tileLength)
40	    {
41	        int64_t blockIdx = AscendC::GetBlockIdx();
42	
43	        if (blockIdx < formerNum) {
44	            this->blockLength = formerLength;
45	            int64_t offset = formerLength * blockIdx;
46	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
47	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
48	        } else {
49	            this->blockLength = tailLength;
50	            int64_t tailIdx = blockIdx - formerNum;
51	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
52	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
53	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
54	        }
55	
56	        this->tileLength = tileLength;
57	
58	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
59	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
60	
61	        // For fp16/bf16 and integer types: allocate FP32 temp buffers for upcast computation
62	        // (AIV Abs only supports half/float, not int32/int64)
63	        if constexpr (sizeof(T) == 2) {
64	            pipe.InitBuffer(tempBufX, tileLength * sizeof(float));
65	            pipe.InitBuffer(tempBufY, tileLength * sizeof(float));
66	        } else if constexpr (std::is_integral_v<T>) {
67	            pipe.InitBuffer(tempBufX, tileLength * sizeof(float));
68	            pipe.InitBuffer(tempBufY, tileLength * sizeof(float));
69	        }
70	    }
71	
72	    __aicore__ inline void Process()
73	    {
74	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
75	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
76	
77	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
78	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
79	
80	        for (int64_t i = 0; i < tileNum - 1; ++i) {
81	            CopyIn(i, this->tileLength);
82	            Compute(i, this->tileLength);
83	            CopyOut(i, this->tileLength);
84	        }
85	        if (tileNum > 0) {
86	            CopyIn(tileNum - 1, alignedTailLen);
87	            Compute(tileNum - 1, alignedTailLen);
88	            CopyOut(tileNum - 1, alignedTailLen);
89	        }
90	    }
91	
92	private:
93	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
94	    {
95	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
96	        CopyInHelper(xLocal, xGm[progress * this->tileLength], static_cast<uint32_t>(curTileLength));
97	        inQueueX.EnQue(xLocal);
98	    }
99	
100	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
101	    {
102	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
103	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
104	
105	        int32_t count = static_cast<int32_t>(curTileLength);
106	
107	        if constexpr (sizeof(T) == 2) {
108	            // fp16 or bfloat16: Cast to FP32 → Abs → Cast back
109	            AscendC::LocalTensor<float> xFp32 = tempBufX.Get<float>();
110	            AscendC::LocalTensor<float> yFp32 = tempBufY.Get<float>();
111	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, count);
112	            AscendC::Abs(yFp32, xFp32, count);
113	            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, count);
114	        } else if constexpr (std::is_same_v<T, float>) {
115	            // float32: direct Abs (supported on both AIC and AIV)
116	            AscendC::Abs(yLocal, xLocal, count);
117	        } else if constexpr (std::is_same_v<T, int32_t>) {
118	            // int32: Cast to FP32 → Abs → Cast back (AIV Abs only supports half/float)
119	            AscendC::LocalTensor<float> xFp32 = tempBufX.Get<float>();
120	            AscendC::LocalTensor<float> yFp32 = tempBufY.Get<float>();
121	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, count);
122	            AscendC::Abs(yFp32, xFp32, count);
123	            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, count);
124	        } else {
125	            // int64: int64→int32→float→Abs→int32→int64 chain
126	            // (int64↔float Cast not supported on c220 AIV)
127	            AscendC::LocalTensor<int32_t> xI32 = tempBufX.Get<int32_t>();
128	            AscendC::Cast(xI32, xLocal, AscendC::RoundMode::CAST_NONE, count);
129	
130	            AscendC::LocalTensor<float> xFp32 = tempBufY.Get<float>();
131	            AscendC::Cast(xFp32, xI32, AscendC::RoundMode::CAST_NONE, count);
132	
133	            AscendC::LocalTensor<float> yFp32 = tempBufX.Get<float>();
134	            AscendC::Abs(yFp32, xFp32, count);
135	
136	            AscendC::LocalTensor<int32_t> yI32 = tempBufY.Get<int32_t>();
137	            AscendC::Cast(yI32, yFp32, AscendC::RoundMode::CAST_ROUND, count);
138	
139	            AscendC::Cast(yLocal, yI32, AscendC::RoundMode::CAST_NONE, count);
140	        }
141	
142	        outQueueY.EnQue<T>(yLocal);
143	        inQueueX.FreeTensor(xLocal);
144	    }
145	
146	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
147	    {
148	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
149	        CopyOutHelper(yGm[progress * this->tileLength], yLocal, static_cast<uint32_t>(curTileLength));
150	        outQueueY.FreeTensor(yLocal);
151	    }
152	
153	private:
154	    AscendC::TPipe pipe;
155	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
156	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
157	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufX;
158	    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufY;
159	    AscendC::GlobalTensor<T> xGm;
160	    AscendC::GlobalTensor<T> yGm;
161	    int64_t blockLength;
162	    int64_t tileLength;
163	};
164	
165	// dtypeFlag: 0=float16, 1=bfloat16, 2=float32, 3=int32, 4=int64
166	extern "C" __global__ __aicore__ void abs_math(GM_ADDR x, GM_ADDR y,
167	                                                int64_t formerNum, int64_t formerLength,
168	                                                int64_t tailLength, int64_t tileLength,
169	                                                int64_t dtypeSize, int64_t dtypeFlag)
170	{
171	    if (dtypeFlag == 0) {
172	        KernelAbsMath<half> op;
173	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
174	        op.Process();
175	    } else if (dtypeFlag == 1) {
176	        KernelAbsMath<bfloat16_t> op;
177	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
178	        op.Process();
179	    } else if (dtypeFlag == 2) {
180	        KernelAbsMath<float> op;
181	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
182	        op.Process();
183	    } else if (dtypeFlag == 3) {
184	        KernelAbsMath<int32_t> op;
185	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
186	        op.Process();
187	    } else if (dtypeFlag == 4) {
188	        KernelAbsMath<int64_t> op;
189	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
190	        op.Process();
191	    }
192	}
