8	constexpr int32_t NB = 2;
9	
10	// ============================================================================
11	// float32 direct: Sub -> Dup(0)->Sub(neg) -> Max -> Dup(1)->Min -> Sub(1-d) -> Cast
12	// Uses 1 workBuf (4x tileLen floats: diff, neg/ones, zero, temp)
13	// ============================================================================
14	struct EqFloat32 {
15	    AscendC::TPipe p;
16	    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
17	    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
18	    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
19	    AscendC::GlobalTensor<float> gX, gY; AscendC::GlobalTensor<int32_t> gZ;
20	    int64_t bL, tL;
21	
22	    __aicore__ inline void init(GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
23	        int64_t bidx = AscendC::GetBlockIdx();
24	        if (bidx < fn) { bL = fl; int64_t off = fl*bidx;
25	            gX.SetGlobalBuffer((__gm__ float*)i1+off,fl); gY.SetGlobalBuffer((__gm__ float*)i2+off,fl);
26	            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,fl);
27	        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn+tl*ti;
28	            gX.SetGlobalBuffer((__gm__ float*)i1+off,tl); gY.SetGlobalBuffer((__gm__ float*)i2+off,tl);
29	            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,tl);
30	        }
31	        tL = tlen;
32	        p.InitBuffer(qX,NB,tlen*4); p.InitBuffer(qY,NB,tlen*4); p.InitBuffer(qZ,NB,tlen*4);
33	        p.InitBuffer(wBuf,tlen*16); // 4 x tileLen floats
34	    }
35	    __aicore__ inline void process() { int64_t tn=(bL+tL-1)/tL, tail=bL-(tn-1)*tL;
36	        for (int64_t i=0; i<tn; ++i) { int64_t c=i==tn-1?tail:tL; ci(i,c); cm(c); co(i,c); } }
37	    __aicore__ inline void ci(int64_t pr, int64_t l) {
38	        { auto x=qX.AllocTensor<float>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
39	          AscendC::DataCopyPadExtParams<float> pp{true,0,0,0.0f}; AscendC::DataCopyPad(x,gX[pr*tL],cp,pp); qX.EnQue(x); }
40	        { auto y=qY.AllocTensor<float>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
41	          AscendC::DataCopyPadExtParams<float> pp{true,0,0,0.0f}; AscendC::DataCopyPad(y,gY[pr*tL],cp,pp); qY.EnQue(y); }
42	    }
43	    __aicore__ inline void cm(int64_t l) {
44	        auto x=qX.DeQue<float>(); auto y=qY.DeQue<float>(); auto z=qZ.AllocTensor<int32_t>();
45	        auto w=wBuf.Get<float>(tL*4); auto d=w, n=w[tL], o=w[tL*2], zt=w[tL*3];
46	        AscendC::Sub(d,x,y,l); AscendC::Duplicate(zt,0.0f,l); AscendC::Sub(n,zt,d,l);
47	        AscendC::Max(d,d,n,l); AscendC::Muls(d,d,1e7f,l); AscendC::Duplicate(o,1.0f,l);
48	        AscendC::Min(d,d,o,l); AscendC::Sub(o,o,d,l); AscendC::Cast(z,o,AscendC::RoundMode::CAST_RINT,l);
49	        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
50	    }
51	    __aicore__ inline void co(int64_t pr, int64_t l) {
52	        auto z=qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
53	        AscendC::DataCopyPad(gZ[pr*tL],z,cp); qZ.FreeTensor(z);
54	    }
55	};
