58	// int32 direct: same pattern, result directly in z
59	// ============================================================================
60	struct EqInt32 {
61	    AscendC::TPipe p;
62	    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
63	    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
64	    AscendC::TBuf<AscendC::TPosition::VECCALC> wBuf;
65	    AscendC::GlobalTensor<int32_t> gX, gY, gZ;
66	    int64_t bL, tL;
67	
68	    __aicore__ inline void init(GM_ADDR i1, GM_ADDR i2, GM_ADDR o, int64_t fn, int64_t fl, int64_t tl, int64_t tlen) {
69	        int64_t bidx = AscendC::GetBlockIdx();
70	        if (bidx < fn) { bL = fl; int64_t off = fl*bidx;
71	            gX.SetGlobalBuffer((__gm__ int32_t*)i1+off,fl); gY.SetGlobalBuffer((__gm__ int32_t*)i2+off,fl);
72	            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,fl);
73	        } else { bL = tl; int64_t ti = bidx-fn; int64_t off = fl*fn+tl*ti;
74	            gX.SetGlobalBuffer((__gm__ int32_t*)i1+off,tl); gY.SetGlobalBuffer((__gm__ int32_t*)i2+off,tl);
75	            gZ.SetGlobalBuffer((__gm__ int32_t*)o+off,tl);
76	        }
77	        tL = tlen;
78	        p.InitBuffer(qX,NB,tlen*4); p.InitBuffer(qY,NB,tlen*4); p.InitBuffer(qZ,NB,tlen*4);
79	        p.InitBuffer(wBuf,tlen*16);
80	    }
81	    __aicore__ inline void process() { int64_t tn=(bL+tL-1)/tL, tail=bL-(tn-1)*tL;
82	        for (int64_t i=0; i<tn; ++i) { int64_t c=i==tn-1?tail:tL; ci(i,c); cm(c); co(i,c); } }
83	    __aicore__ inline void ci(int64_t pr, int64_t l) {
84	        { auto x=qX.AllocTensor<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
85	          AscendC::DataCopyPadExtParams<int32_t> pp{true,0,0,0}; AscendC::DataCopyPad(x,gX[pr*tL],cp,pp); qX.EnQue(x); }
86	        { auto y=qY.AllocTensor<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
87	          AscendC::DataCopyPadExtParams<int32_t> pp{true,0,0,0}; AscendC::DataCopyPad(y,gY[pr*tL],cp,pp); qY.EnQue(y); }
88	    }
89	    __aicore__ inline void cm(int64_t l) {
90	        auto x=qX.DeQue<int32_t>(); auto y=qY.DeQue<int32_t>(); auto z=qZ.AllocTensor<int32_t>();
91	        auto w=wBuf.Get<int32_t>(tL*4); auto d=w, n=w[tL], o=w[tL*2], zt=w[tL*3];
92	        AscendC::Sub(d,x,y,l); AscendC::Duplicate(zt,(int32_t)0,l); AscendC::Sub(n,zt,d,l);
93	        AscendC::Max(d,d,n,l); AscendC::Duplicate(o,(int32_t)1,l); AscendC::Min(d,d,o,l);
94	        AscendC::Sub(z,o,d,l);
95	        qZ.EnQue<int32_t>(z); qX.FreeTensor(x); qY.FreeTensor(y);
96	    }
97	    __aicore__ inline void co(int64_t pr, int64_t l) {
98	        auto z=qZ.DeQue<int32_t>(); AscendC::DataCopyExtParams cp{1,(uint32_t)(l*4),0,0,0};
99	        AscendC::DataCopyPad(gZ[pr*tL],z,cp); qZ.FreeTensor(z);
100	    }
101	};
