103	// ============================================================================
104	// half/bf16: Cast float32 then same logic. 2 work bufs: castBuf(2x) + compBuf(4x)
105	// ============================================================================
106	template <typename SrcT>
107	struct EqFp16Like {
108	    AscendC::TPipe p;
109	    AscendC::TQue<AscendC::TPosition::VECIN, NB> qX, qY;
110	    AscendC::TQue<AscendC::TPosition::VECOUT, NB> qZ;
111	    AscendC::TBuf<AscendC::TPosition::VECCALC> cBuf, wBuf;
112	    AscendC::GlobalTensor<SrcT> gX, gY; AscendC::GlobalTensor<int32_t> gZ;
113	    int64_t bL, tL;
114	    static constexpr int64_t sz = sizeof(SrcT);
115	
