#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Helper: CopyIn (GM -> UB)
template <typename T>
__aicore__ inline void CopyInHelper(AscendC::LocalTensor<T> &dst, const AscendC::GlobalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

// Helper: CopyOut (UB -> GM)
template <typename T>
__aicore__ inline void CopyOutHelper(const AscendC::GlobalTensor<T> &dst, AscendC::LocalTensor<T> &src, uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
class KernelIsFinite {
public:
    __aicore__ inline KernelIsFinite() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        // Compare+Select approach buffers
        // cmpBuf: uint8_t for Compare output (1 byte per element for safety)
        pipe.InitBuffer(cmpBuf, tileLength);

        if constexpr (sizeof(T) == 2) {
            // float16: Cast to FP32 -> compute -> Cast back
            // castBuf: xFp32 (tL floats) + result (tL floats)
            pipe.InitBuffer(castBuf, tileLength * 8);
            // workBuf: diff (tL floats) + ones (tL floats)
            pipe.InitBuffer(workBuf, tileLength * 8);
        } else {
            // float32: diff (tL floats) + ones (tL floats)
            pipe.InitBuffer(workBuf, tileLength * 8);
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        CopyInHelper(xLocal, xGm[progress * this->tileLength], static_cast<uint32_t>(curTileLength));
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        int32_t count = static_cast<int32_t>(curTileLength);

        // cmpMask output from Compare: bit-packed uint8_t
        AscendC::LocalTensor<uint8_t> cmpMask = cmpBuf.Get<uint8_t>(this->tileLength);

        if constexpr (sizeof(T) == 2) {
            // float16 path: Cast input to FP32
            AscendC::LocalTensor<float> cf = castBuf.Get<float>(this->tileLength * 2);
            AscendC::LocalTensor<float> xFp32 = cf;
            AscendC::LocalTensor<float> resFp32 = cf[this->tileLength];
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, count);

            AscendC::LocalTensor<float> w = workBuf.Get<float>(this->tileLength * 2);
            AscendC::LocalTensor<float> diff = w;
            AscendC::LocalTensor<float> ones = w[this->tileLength];

            // diff = x - x: 0 for finite, NaN for inf/NaN
            AscendC::Sub(diff, xFp32, xFp32, count);
            // Compare(diff, diff, EQ): NaN!=NaN → 0bit, 0==0 → 1bit → isfinite mask
            AscendC::Compare(cmpMask, diff, diff, AscendC::CMPMODE::EQ, count);
            // ones = 1.0
            AscendC::Duplicate(ones, 1.0f, count);
            // Select: mask bit=1 → src0(ones)=1.0, bit=0 → scalar(0)=0.0
            AscendC::Select(resFp32, cmpMask, ones, 0.0f,
                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, count);
            // Cast back to half
            AscendC::Cast(yLocal, resFp32, AscendC::RoundMode::CAST_ROUND, count);
        } else {
            // float32 path: direct computation
            AscendC::LocalTensor<float> w = workBuf.Get<float>(this->tileLength * 2);
            AscendC::LocalTensor<float> diff = w;
            AscendC::LocalTensor<float> ones = w[this->tileLength];

            // diff = x - x: 0 for finite, NaN for inf/NaN
            AscendC::Sub(diff, xLocal, xLocal, count);
            // Compare(diff, diff, EQ): NaN!=NaN → 0bit, 0==0 → 1bit → isfinite mask
            AscendC::Compare(cmpMask, diff, diff, AscendC::CMPMODE::EQ, count);
            // ones = 1.0
            AscendC::Duplicate(ones, 1.0f, count);
            // Select: mask bit=1 → src0(ones)=1.0, bit=0 → scalar(0)=0.0
            AscendC::Select(yLocal, cmpMask, ones, 0.0f,
                            AscendC::SELMODE::VSEL_TENSOR_SCALAR_MODE, count);
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        CopyOutHelper(yGm[progress * this->tileLength], yLocal, static_cast<uint32_t>(curTileLength));
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
};

